<script>
    (function () {
        var form = document.getElementById('busca-form-main');
        var input = document.getElementById('busca-input-plain');
        var hiddenBusca = form ? form.querySelector('input[name="busca"]') : null;
        var hiddenMode = form ? form.querySelector('input[name="busca_mode"]') : null;
        var hiddenTipo = form ? form.querySelector('input[name="busca_tipo"]') : null;
        var aiInput = document.getElementById('busca-input-ai');
        var typeButtons = form ? Array.prototype.slice.call(form.querySelectorAll('[data-busca-tipo]')) : [];
        var mobileDropdown = form ? form.querySelector('[data-busca-mobile-dropdown]') : null;
        var mobileTrigger = mobileDropdown ? mobileDropdown.querySelector('.busca-type-mobile-trigger') : null;
        var mobileTriggerIcon = mobileDropdown ? mobileDropdown.querySelector('[data-busca-mobile-icon]') : null;
        var mobileTriggerLabel = mobileDropdown ? mobileDropdown.querySelector('[data-busca-mobile-label]') : null;
        var aiButton = form ? form.querySelector('[data-busca-mode="ai"]') : null;
        var aiAllowed = aiButton ? aiButton.dataset.buscaAiAllowed === 'true' : false;

        if (!form || !input || !hiddenBusca || !hiddenMode || !hiddenTipo) {
            return;
        }

        var typeMeta = {
            todos: { label: 'Todos', icon: 'fa-layer-group' },
            eventos: { label: 'Eventos', icon: 'fa-calendar-days' },
            resultados: { label: 'Resultados', icon: 'fa-medal' },
            atletas: { label: 'Atletas', icon: 'fa-user' },
            noticias: { label: 'Not\xEDcias', icon: 'fa-newspaper' },
            videos: { label: 'V\xEDdeos', icon: 'fa-youtube' }
        };

        function syncValue() {
            hiddenBusca.value = input.value;
            if (aiInput) {
                aiInput.value = input.value;
            }
        }

        function closeMobileDropdown() {
            if (!mobileDropdown || !mobileTrigger) {
                return;
            }

            mobileDropdown.classList.remove('is-open');
            mobileTrigger.setAttribute('aria-expanded', 'false');
        }

        function updateMobileTrigger(type) {
            var meta = typeMeta[type] || typeMeta.todos;

            if (mobileTriggerIcon) {
                mobileTriggerIcon.className = 'fa-solid ' + meta.icon;

                if (type === 'videos') {
                    mobileTriggerIcon.className = 'fa-brands fa-youtube';
                }
            }

            if (mobileTriggerLabel) {
                mobileTriggerLabel.textContent = meta.label;
            }
        }

        function setType(type) {
            var normalizedType = ['todos', 'eventos', 'resultados', 'atletas', 'noticias', 'videos'].indexOf(type) >= 0 ? type : 'todos';
            hiddenTipo.value = normalizedType;
            typeButtons.forEach(function (button) {
                button.classList.toggle('is-active', button.dataset.buscaTipo === normalizedType);
            });
            updateMobileTrigger(normalizedType);

            if (aiButton) {
                aiButton.classList.toggle('is-active', hiddenMode.value === 'ai');
                aiButton.setAttribute('aria-pressed', hiddenMode.value === 'ai' ? 'true' : 'false');
            }
        }

        function toggleAi(event) {
            if (event) {
                event.stopImmediatePropagation();
            }

            if (!aiAllowed) {
                return;
            }

            hiddenMode.value = hiddenMode.value === 'ai' ? 'plain' : 'ai';

            if (aiButton) {
                aiButton.classList.toggle('is-active', hiddenMode.value === 'ai');
                aiButton.setAttribute('aria-pressed', hiddenMode.value === 'ai' ? 'true' : 'false');
            }
        }

        if (typeButtons.length) {
            typeButtons.forEach(function (button) {
                button.addEventListener('click', function () {
                    setType(button.dataset.buscaTipo);
                    closeMobileDropdown();
                });
            });
        }

        if (mobileTrigger) {
            mobileTrigger.addEventListener('click', function (event) {
                event.preventDefault();
                event.stopPropagation();
                mobileDropdown.classList.toggle('is-open');
                mobileTrigger.setAttribute('aria-expanded', mobileDropdown.classList.contains('is-open') ? 'true' : 'false');
            });
        }

        document.addEventListener('click', function (event) {
            if (!mobileDropdown || mobileDropdown.contains(event.target)) {
                return;
            }

            closeMobileDropdown();
        });

        if (aiButton) {
            aiButton.addEventListener('click', toggleAi);
        }

        form.addEventListener('submit', function () {
            syncValue();
        });

        input.addEventListener('input', syncValue);
        setType(hiddenTipo.value);
    })();
</script>

