                            onclick="return window.RRSeguidoresToggleSuggestions ? window.RRSeguidoresToggleSuggestions(this, event) : true;">
                        <i class="fa-solid fa-user-plus"></i>
                    </button>
                    <div class="btn-group btn-group shadow-0" role="group" aria-label="Ordenação">
                        <button type="button"
                                class="btn btn btn-primary p-2"
                                data-mdb-ripple-init
                                data-seguidores-order="atual"
                                title="Atual">
                            <i class="fa-solid fa-arrow-down-wide-short"></i>
                        </button>
                        <button type="button"
                                class="btn btn btn-secondary p-2"
                                data-mdb-ripple-init
                                data-seguidores-order="alfabetica"
                                title="A-Z">
                            <i class="fa-solid fa-arrow-down-a-z"></i>
