</div>



<script>

    let escopo = 'pagina';
    let countseguindo = '';
    let countseguidores = '';
    const followersLabel = 'seguidores';
    const followingLabel = 'seguindo';
    const followersFetchError = 'Algo deu errado.';
    const currentFollowersLang = 'pt-BR';
    const seguidoresViewerPageId = '0';
    const seguidoresContextPageId = '0';
    const followersSuggestionsLoading = 'Carregando contatos sugeridos...';
    const followersSuggestionsEmpty = 'Nenhum contato sugerido disponível agora.';
    let ultimoTipoSeguidores = followersLabel;
    let ordemSeguidores = 'atual';
    let seguidoresSuggestionsVisible = false;
    let seguidoresRequestId = 0;
    let seguidoresSuggestionsRequestId = 0;

    function buildSeguidoresUrl(tipoAtual) {
        if (escopo === 'perfil') {
            return '/api/seguidores.cfm?id_pagina=0&id_pagina_perfil=0&tipo=' + encodeURIComponent(tipoAtual) + '&escopo=' + escopo + '&ordem=' + encodeURIComponent(ordemSeguidores) + '&i18n_lang=' + encodeURIComponent(currentFollowersLang);
        }

        return '/api/seguidores.cfm?id_pagina=&id_pagina_perfil=0&tipo=' + encodeURIComponent(tipoAtual) + '&escopo=' + escopo + '&ordem=' + encodeURIComponent(ordemSeguidores) + '&i18n_lang=' + encodeURIComponent(currentFollowersLang);
    }

    function getSeguidoresVisibleContactIds(modalElement) {
        const listContainer = modalElement ? modalElement.querySelector('[data-seguidores-list]') : null;
        const ids = [];

        if (!listContainer) {
            return ids;
        }

        listContainer.querySelectorAll('[data-modal-contact-id]').forEach(function (item) {
            const id = parseInt(item.getAttribute('data-modal-contact-id') || '0', 10);

            if (id > 0 && !ids.includes(id)) {
                ids.push(id);
            }
        });

        return ids;
    }

    function buildSeguidoresSuggestionsUrl(modalElement) {
        const params = new URLSearchParams({
            limit: '12',
            i18n_lang: currentFollowersLang,
            source: 'followers_modal',
            source_page_id: escopo === 'perfil' ? seguidoresViewerPageId : seguidoresContextPageId,
            source_tipo: isSeguidoresType(ultimoTipoSeguidores) ? 'seguidores' : 'seguindo',
            _: Date.now().toString()
        });
        const visibleContactIds = getSeguidoresVisibleContactIds(modalElement).slice(0, 200);

        if (visibleContactIds.length) {
            params.set('exclude', visibleContactIds.join(','));
        }

        return '/api/sugestoes_contatos.cfm?' + params.toString();
    }

    function buildSeguidoresGeneralSuggestionsUrl(modalElement) {
        const params = new URLSearchParams({
            limit: '10',
            _: Date.now().toString()
        });
        const visibleContactIds = getSeguidoresVisibleContactIds(modalElement).slice(0, 200);

        if (visibleContactIds.length) {
            params.set('exclude', visibleContactIds.join(','));
        }

        return '/api/sugestoes_contatos.cfm?' + params.toString();
    }

    function removeVisibleSuggestionsFromSlot(modalElement, slot) {
        const visibleContactIds = getSeguidoresVisibleContactIds(modalElement).map(function (id) {
            return String(id);
        });

        if (!slot || !visibleContactIds.length) {
            return true;
        }

        slot.querySelectorAll('.activities-contact-suggestion[data-contact-id]').forEach(function (item) {
            if (visibleContactIds.includes(String(item.getAttribute('data-contact-id') || ''))) {
                item.remove();
            }
        });

        return !!slot.querySelector('.activities-contact-suggestion[data-contact-id]');
    }

    function renderSeguidoresSuggestionsHtml(modalElement, slot, html) {
        const trimmedHtml = String(html || '').trim();

        if (!trimmedHtml) {
            return false;
        }

        slot.innerHTML = trimmedHtml;

        if (!removeVisibleSuggestionsFromSlot(modalElement, slot)) {
            return false;
        }

        slot.querySelectorAll('.activities-contact-suggestion[data-contact-id]').forEach(function (item, index) {
            if (index >= 4) {
                item.remove();
            }
        });

        slot.dataset.loaded = '1';

        if (window.RRContactSuggestions && typeof window.RRContactSuggestions.init === 'function') {
            window.RRContactSuggestions.init(slot);
        }

        return true;
    }

    function fetchSeguidoresSuggestionsHtml(url) {
        return fetch(url, {
            credentials: 'same-origin',
            headers: {
                'X-Requested-With': 'XMLHttpRequest'
            }
        }).then(function (response) {
            if (!response.ok) {
                throw new Error('suggestions failed');
            }

            return response.text();
        });
    }

    function escapeSeguidoresAttribute(value) {
        return String(value || '').replace(/[&<>"']/g, function (character) {
            return {
                '&': '&amp;',
                '<': '&lt;',
                '>': '&gt;',
                '"': '&quot;',
                "'": '&#039;'
            }[character];
        });
    }

    function buildSeguidoresSuggestionsPlaceholder() {
        const rows = Array.from({ length: 4 }).map(function () {
            return [
                '<div class="followers-modal-suggestions-placeholder-row" aria-hidden="true">',
                    '<div class="followers-modal-suggestions-placeholder-profile">',
                        '<span class="followers-modal-skeleton followers-modal-skeleton-avatar"></span>',
                        '<span class="followers-modal-skeleton-lines">',
                            '<span class="followers-modal-skeleton followers-modal-skeleton-name"></span>',
                            '<span class="followers-modal-skeleton followers-modal-skeleton-tag"></span>',
                            '<span class="followers-modal-skeleton followers-modal-skeleton-context"></span>',
                        '</span>',
                    '</div>',
                    '<span class="followers-modal-skeleton followers-modal-skeleton-action"></span>',
                '</div>'
            ].join('');
        }).join('');

        return [
            '<section class="followers-modal-suggestions-placeholder" aria-label="', escapeSeguidoresAttribute(followersSuggestionsLoading), '">',
                '<div class="followers-modal-suggestions-placeholder-header" aria-hidden="true">',
                    '<span class="followers-modal-skeleton followers-modal-skeleton-icon"></span>',
                    '<span class="followers-modal-skeleton followers-modal-skeleton-title"></span>',
                '</div>',
                '<div class="followers-modal-suggestions-placeholder-list">',
                    rows,
                '</div>',
            '</section>'
        ].join('');
    }

    function hydrateSeguidoresStateFromTrigger(trigger, fallbackTipo) {
        if (trigger && trigger.getAttribute) {
            if (trigger.getAttribute('data-mdb-countseguindo')) {
                countseguindo = trigger.getAttribute('data-mdb-countseguindo');
            }
            if (trigger.getAttribute('data-mdb-countseguidores')) {
                countseguidores = trigger.getAttribute('data-mdb-countseguidores');
            }
            if (trigger.getAttribute('data-mdb-escopo')) {
                escopo = trigger.getAttribute('data-mdb-escopo');
            }
            if (trigger.getAttribute('data-mdb-tipo')) {
                ultimoTipoSeguidores = trigger.getAttribute('data-mdb-tipo');
            } else if (fallbackTipo) {
                ultimoTipoSeguidores = fallbackTipo;
            }
        } else if (fallbackTipo) {
            ultimoTipoSeguidores = fallbackTipo;
        }

        return ultimoTipoSeguidores;
    }

    function isSeguidoresType(tipoAtual) {
        return tipoAtual === followersLabel || ['seguidores', 'followers'].includes(String(tipoAtual).toLowerCase());
    }

    function getSeguidoresSwitchLabel(targetType) {
        return targetType === 'seguindo' ? followingLabel : followersLabel;
    }

    function updateSeguidoresSwitchState(modalElement, tipoAtual) {
        const activeType = isSeguidoresType(tipoAtual) ? 'seguidores' : 'seguindo';

        modalElement.querySelectorAll('[data-seguidores-switch]').forEach((button) => {
            const isActive = button.getAttribute('data-seguidores-switch') === activeType;

            button.classList.toggle('btn-primary', isActive);
            button.classList.toggle('btn-secondary', !isActive);
            button.setAttribute('aria-pressed', isActive ? 'true' : 'false');
        });
    }

    function updateSeguidoresOrderState(modalElement) {
        modalElement.querySelectorAll('[data-seguidores-order]').forEach((button) => {
            const isActive = button.getAttribute('data-seguidores-order') === ordemSeguidores;

            button.classList.toggle('btn-primary', isActive);
            button.classList.toggle('btn-secondary', !isActive);
            button.setAttribute('aria-pressed', isActive ? 'true' : 'false');
        });
    }

    function updateSeguidoresSuggestionsToggleState(modalElement) {
        const button = modalElement.querySelector('[data-seguidores-suggestions-toggle]');

        if (!button) {
            return;
        }

        button.classList.toggle('btn-primary', seguidoresSuggestionsVisible);
        button.classList.toggle('btn-secondary', !seguidoresSuggestionsVisible);
        button.setAttribute('aria-expanded', seguidoresSuggestionsVisible ? 'true' : 'false');
    }

    function ensureSeguidoresModalContainers(modalElement) {
        const modalBody = modalElement.querySelector('.modal-body');

        if (!modalBody) {
            return {
                slot: null,
                list: null
            };
        }

        let slot = modalBody.querySelector('[data-seguidores-suggestions-slot]');
        let listContainer = modalBody.querySelector('[data-seguidores-list]');

        if (!slot) {
            slot = document.createElement('div');
            slot.className = 'followers-modal-suggestions-slot';
            slot.setAttribute('data-seguidores-suggestions-slot', '');
            slot.hidden = true;
            modalBody.insertBefore(slot, modalBody.firstChild);
        }

        if (!listContainer) {
            listContainer = document.createElement('div');
            listContainer.setAttribute('data-seguidores-list', '');

            Array.prototype.slice.call(modalBody.childNodes).forEach((node) => {
                if (node !== slot && node !== listContainer) {
                    listContainer.appendChild(node);
                }
            });

            modalBody.appendChild(listContainer);
        }

        return {
            slot: slot,
            list: listContainer
        };
    }

    function renderSeguidoresModalBody(modalElement, html) {
        const containers = ensureSeguidoresModalContainers(modalElement);
        const listContainer = containers.list;

        if (listContainer) {
            listContainer.innerHTML = html;
        }

        if (seguidoresSuggestionsVisible) {
            loadSeguidoresSuggestions(modalElement, true);
        }
    }

    function loadSeguidoresSuggestions(modalElement, forceReload) {
        const containers = ensureSeguidoresModalContainers(modalElement);
        const slot = containers.slot;
        const modalBody = modalElement.querySelector('.modal-body');

        if (!slot) {
            return Promise.resolve(false);
        }

        if (!forceReload && slot.dataset.loaded === '1') {
            slot.hidden = false;
            return Promise.resolve(true);
        }

        const requestId = ++seguidoresSuggestionsRequestId;
        slot.hidden = false;
        slot.dataset.loading = '1';
        slot.innerHTML = buildSeguidoresSuggestionsPlaceholder();

        if (modalBody) {
            modalBody.scrollTop = 0;
        }

        return fetchSeguidoresSuggestionsHtml(buildSeguidoresSuggestionsUrl(modalElement))
            .then(function (html) {
                if (requestId !== seguidoresSuggestionsRequestId) {
                    return false;
                }

                if (renderSeguidoresSuggestionsHtml(modalElement, slot, html)) {
                    return true;
                }

                return fetchSeguidoresSuggestionsHtml(buildSeguidoresGeneralSuggestionsUrl(modalElement))
                    .then(function (fallbackHtml) {
                        if (requestId !== seguidoresSuggestionsRequestId) {
                            return false;
                        }

                        if (renderSeguidoresSuggestionsHtml(modalElement, slot, fallbackHtml)) {
                            return true;
                        }

                        slot.innerHTML = '<div class="followers-modal-suggestions-empty">' + followersSuggestionsEmpty + '</div>';
                        slot.hidden = false;
                        updateSeguidoresSuggestionsToggleState(modalElement);
                        return false;
                    });
            })
            .catch(function (err) {
                console.warn(followersFetchError, err);
                return fetchSeguidoresSuggestionsHtml(buildSeguidoresGeneralSuggestionsUrl(modalElement))
                    .then(function (fallbackHtml) {
                        if (requestId !== seguidoresSuggestionsRequestId) {
                            return false;
                        }

                        if (renderSeguidoresSuggestionsHtml(modalElement, slot, fallbackHtml)) {
                            return true;
                        }

                        slot.innerHTML = '<div class="followers-modal-suggestions-empty">' + followersSuggestionsEmpty + '</div>';
                        slot.hidden = false;
                        updateSeguidoresSuggestionsToggleState(modalElement);
                        return false;
                    })
                    .catch(function () {
                        slot.innerHTML = '<div class="followers-modal-suggestions-empty">' + followersSuggestionsEmpty + '</div>';
                        slot.hidden = false;
                        updateSeguidoresSuggestionsToggleState(modalElement);
                        return false;
                    });
            })
            .finally(function () {
                slot.dataset.loading = '0';
            });
    }

    function toggleSeguidoresSuggestions(modalElement) {
        const containers = ensureSeguidoresModalContainers(modalElement);
        const slot = containers.slot;
        const modalBody = modalElement.querySelector('.modal-body');

        seguidoresSuggestionsVisible = !seguidoresSuggestionsVisible;
        updateSeguidoresSuggestionsToggleState(modalElement);

        if (!slot) {
            return;
        }

        if (!seguidoresSuggestionsVisible) {
            slot.hidden = true;
            return;
        }

        loadSeguidoresSuggestions(modalElement, !slot.dataset.loaded);

        if (modalBody) {
            modalBody.scrollTop = 0;
        }
    }

    window.RRSeguidoresToggleSuggestions = function (button, event) {
        if (event && event.rrSeguidoresSuggestionsHandled) {
            return false;
        }

        const modalElement = button ? button.closest('#modal_seguidores') : null;

        if (!modalElement) {
            return true;
        }

        if (event) {
            event.preventDefault();
            event.rrSeguidoresSuggestionsHandled = true;
        }

        toggleSeguidoresSuggestions(modalElement);
        return false;
    };

    function fillSeguidoresModal(modalElement, tipoAtual) {
        if (!modalElement) {
            return;
        }

        const modalTitle = modalElement.querySelector('.modal-title');
        const counterSeguidores = modalElement.querySelector('.counter-seguidores');
        const counterSeguindo = modalElement.querySelector('.counter-seguindo');

        if (modalTitle) {
            modalTitle.textContent = `${tipoAtual}`;
        }
        if (counterSeguidores) {
            counterSeguidores.textContent = `${countseguindo}`;
        }
        if (counterSeguindo) {
            counterSeguindo.textContent = `${countseguidores}`;
        }
        updateSeguidoresSwitchState(modalElement, tipoAtual);
        updateSeguidoresOrderState(modalElement);
        updateSeguidoresSuggestionsToggleState(modalElement);

        const requestId = ++seguidoresRequestId;

        fetch(buildSeguidoresUrl(tipoAtual))
            .then(function (response) {
                return response.text();
            }).then(function (html) {
                if (requestId === seguidoresRequestId) {
                    renderSeguidoresModalBody(modalElement, html);
                }
            }).catch(function (err) {
                console.warn(followersFetchError, err);
            });
    }

    const modalSeguidores = document.getElementById('modal_seguidores');

    if (modalSeguidores) {
        modalSeguidores.addEventListener('show.mdb.modal', (e) => {
            const button = e.relatedTarget;
            const pendingTipo = modalSeguidores.dataset.pendingTipo || followersLabel;
            const tipoAtual = hydrateSeguidoresStateFromTrigger(button, pendingTipo);
            seguidoresSuggestionsVisible = false;
            seguidoresSuggestionsRequestId++;
            updateSeguidoresSuggestionsToggleState(modalSeguidores);
            fillSeguidoresModal(modalSeguidores, tipoAtual);
            delete modalSeguidores.dataset.pendingTipo;
        });

        modalSeguidores.querySelectorAll('[data-seguidores-switch]').forEach((button) => {
            button.addEventListener('click', () => {
                const tipoAtual = getSeguidoresSwitchLabel(button.getAttribute('data-seguidores-switch'));

                if (tipoAtual === ultimoTipoSeguidores) {
                    return;
                }

                ultimoTipoSeguidores = tipoAtual;
                fillSeguidoresModal(modalSeguidores, tipoAtual);
            });
        });

        modalSeguidores.querySelectorAll('[data-seguidores-order]').forEach((button) => {
            button.addEventListener('click', () => {
                const novaOrdem = button.getAttribute('data-seguidores-order') || 'atual';

                if (novaOrdem === ordemSeguidores) {
                    return;
                }

                ordemSeguidores = novaOrdem;
                fillSeguidoresModal(modalSeguidores, ultimoTipoSeguidores);
            });
        });

        modalSeguidores.addEventListener('click', (event) => {
            const followLink = event.target.closest('.activities-contact-follow');

            if (!followLink || !modalSeguidores.contains(followLink)) {
                return;
            }

            const item = followLink.closest('.activities-contact-suggestion');
            const section = followLink.closest('[data-contact-suggestions]');

            if (!item || followLink.dataset.followPending === '1') {
                return;
            }

            event.preventDefault();
            followLink.dataset.followPending = '1';
            item.classList.add('is-following');

            fetch(followLink.href, {
                credentials: 'same-origin',
                headers: {
                    'X-Requested-With': 'XMLHttpRequest'
                },
                redirect: 'follow'
            })
                .then(function (response) {
                    if (!response.ok) {
                        throw new Error('follow failed');
                    }

                    const followedId = parseInt(followLink.getAttribute('data-contact-id') || item.getAttribute('data-contact-id') || '0', 10);

                    item.remove();
                    document.dispatchEvent(new CustomEvent('rr:contact-suggestion-followed', {
                        detail: {
                            id: followedId
                        }
                    }));

                    if (section && window.RRContactSuggestions && typeof window.RRContactSuggestions.refresh === 'function') {
                        window.RRContactSuggestions.refresh(section, {
                            excludeVisible: true,
                            extraExclude: followedId > 0 ? [followedId] : [],
                            reason: 'follow'
                        });
                    } else {
                        loadSeguidoresSuggestions(modalSeguidores, true);
                    }
                })
                .catch(function () {
                    window.location.href = followLink.href;
                });
        });
    }

    document.addEventListener('click', (event) => {
        const suggestionsToggle = event.target.closest('[data-seguidores-suggestions-toggle]');

        if (!suggestionsToggle) {
            return;
        }

        const modalElement = suggestionsToggle.closest('#modal_seguidores');

        if (!modalElement) {
            return;
        }

        window.RRSeguidoresToggleSuggestions(suggestionsToggle, event);
    }, true);

</script>


