          pushMenuItem.style.display = visible ? '' : 'none';
        }
      }

      function setPushPreferencesMenuVisibility(visible) {
        if (pushPreferencesMenuItem) {
          pushPreferencesMenuItem.style.display = visible ? '' : 'none';
        }
      }

