        overflow: hidden;
        text-overflow: ellipsis;
        white-space: nowrap;
    }

    .rr-chat-header-name .rr-user-status-icon {
        display: inline-flex;
        flex: 0 0 auto;
    }

    .rr-notification-item.is-read,
