        background-color: #f5f5f5;
    }

    .rr-notification-item.is-read .rr-notification-item-icon,
    .rr-notification-item.is-read .rr-notification-item-text {
        opacity: .5;
    }

    .rr-notifications-menu {
        width: min(19rem, calc(100vw - 1rem));
