        right: 0;
        left: auto;
    }

    .rr-notification-header {
        display: flex;
        align-items: center;
        justify-content: space-between;
        padding: .25rem .4rem .25rem .25rem;
    }

    .rr-notification-header .dropdown-header {
        padding-top: .35rem;
        padding-bottom: .35rem;
    }

    .rr-notification-actions {
        display: inline-flex;
        align-items: center;
        gap: .35rem;
    }

    .rr-notification-action {
        display: inline-flex;
        align-items: center;
        justify-content: center;
        width: 1.75rem;
        height: 1.75rem;
        padding: 0;
        border: 0;
        border-radius: 50%;
        color: rgba(51, 51, 51, .58);
        background: transparent;
        font-size: .72rem;
    }

    .rr-notification-action:hover,
    .rr-notification-action:focus {
        color: #333333;
        background-color: rgba(51, 51, 51, .08);
    }

    .rr-notification-action:disabled {
        color: rgba(51, 51, 51, .25);
        background: transparent;
    }

    .rr-chat-new-action {
        border-radius: 4px;
    }

    .rr-topbar-right-menu {
        right: 0;
        left: auto;
    }

    .rr-language-switch {
        display: inline-flex;
        align-items: center;
        gap: 0.15rem;
        padding: 0.12rem;
        border-radius: 999px;
        border: 1px solid rgba(51, 51, 51, 0.12);
        background-color: rgba(255, 255, 255, 0.55);
    }

    .rr-language-switch-link {
        display: inline-flex;
        align-items: center;
        justify-content: center;
        min-width: 2rem;
        height: 1.65rem;
        padding: 0 0.45rem;
        border-radius: 999px;
        color: #333333 !important;
        font-size: 0.68rem;
        font-weight: 800;
        letter-spacing: 0.03em;
        text-decoration: none;
        transition: background-color .18s ease, color .18s ease;
    }

    .rr-language-switch-link:hover,
    .rr-language-switch-link:focus {
        background-color: rgba(0, 0, 0, 0.06);
        color: #111111 !important;
        text-decoration: none;
    }

    .rr-language-switch-link.is-active {
        background-color: #333333;
        color: #ffffff !important;
    }

    @media (max-width: 767.98px) {
        .rr-notifications-menu {
            min-width: 0;
            width: min(17rem, calc(100vw - 1rem));
        }

    }
