        const form = document.querySelector("#formincluirevento");

        async function sendData() {
          // Associate the FormData object with the form element
          const formData = new FormData(form);

          try {
            const response = await fetch("/api/incluir_evento.cfm", {
              method: "POST",
              // Set the FormData instance as the request body
              body: formData,
            });
            const resposta = await response.json();
            const mensagemmodalincluirevento = document.getElementById('mensagemmodalincluirevento');
            const successTemplate = "Informação enviada com sucesso. Ticket aberto com o número {ticket}.";
            const closeLabel = "Fechar janela";
            const closeAria = "Fechar";
            const successMessage = successTemplate.replace("{ticket}", resposta.ticket);
            const mensagemHTML = '<div id="divresultadoincluirevento" class="alert alert-success">' + successMessage + '</div><p><button class="btn w-100 btn-primary" type="button" data-mdb-ripple-init data-mdb-dismiss="modal" aria-label="' + closeAria + '">' + closeLabel + '</button></p>';
            // Append an image element generated by createImg function to the container with images
            mensagemmodalincluirevento.insertAdjacentHTML('afterbegin', mensagemHTML);
          } catch (e) {
            console.error(e);
          }
        }

        // Take over form submission
        form.addEventListener("submit", (event) => {
          event.preventDefault();
          sendData();
        });

        const myModalEl = document.getElementById('modal_evento_cadastro')
            myModalEl.addEventListener('hide.mdb.modal', (e) => {
                const mensagemmodalincluirevento = document.getElementById('mensagemmodalincluirevento');
                mensagemmodalincluirevento.innerHTML = "";
                console.log('fechou');
        })

    </script>

