                                data-seguidores-order="atual"
                                title="Atual">
                            <i class="fa-solid fa-arrow-down-wide-short"></i>
                        </button>
                        <button type="button"
                                class="btn btn btn-secondary p-2"
                                data-mdb-ripple-init
                                data-seguidores-order="alfabetica"
                                title="A-Z">
                            <i class="fa-solid fa-arrow-down-a-z"></i>
                        </button>
