            <li><span><i class="fa-solid fa-arrow-up-from-bracket"></i>${rrPwaEscapeHtml(i18n.stepShare)}</span></li>
            <li><span><i class="fa-solid fa-square-plus"></i>${rrPwaEscapeHtml(i18n.stepHome)}</span></li>
          </ul>
