<script>
    (function () {
        function hydrateScripts(container) {
            var scripts = [];

            if (container.matches && container.matches('script')) {
                scripts.push(container);
            }

            container.querySelectorAll('script').forEach(function (oldScript) {
                scripts.push(oldScript);
            });

            scripts.forEach(function (oldScript) {
                var newScript = document.createElement('script');

                Array.prototype.slice.call(oldScript.attributes).forEach(function (attribute) {
                    newScript.setAttribute(attribute.name, attribute.value);
                });

                newScript.text = oldScript.text || oldScript.textContent || '';
                oldScript.parentNode.replaceChild(newScript, oldScript);
            });

            if (window.mdb && typeof window.mdb.AutoInit === 'function') {
                try {
                    window.mdb.AutoInit();
                } catch (error) {
                    console.warn('MDB sidebar async init skipped', error);
                }
            }
        }

        function loadSidebar(target) {
            if (!target || target.dataset.homeSidebarLoaded === '1') {
                return;
            }

            if (!target.getClientRects().length) {
                return;
            }

            target.dataset.homeSidebarLoaded = '1';

            fetch(target.dataset.homeSidebarUrl || '/api/home_sidebar.cfm?i18n_lang=pt\x2DBR', {
                cache: 'no-store',
                credentials: 'same-origin',
                headers: {
                    'X-Requested-With': 'XMLHttpRequest'
                }
            })
                .then(function (response) {
                    if (!response.ok) {
                        throw new Error('home sidebar async failed');
                    }

                    return response.text();
                })
                .then(function (html) {
                    var trimmedHtml = html.trim();

                    if (!trimmedHtml) {
                        target.remove();
                        return;
                    }

                    var wrapper = document.createElement('div');
                    wrapper.innerHTML = trimmedHtml;
                    var fragment = document.createDocumentFragment();

                    while (wrapper.firstChild) {
                        fragment.appendChild(wrapper.firstChild);
                    }

                    var insertedNodes = Array.prototype.slice.call(fragment.childNodes);
                    target.parentNode.replaceChild(fragment, target);
                    insertedNodes.forEach(function (node) {
                        if (node.nodeType === 1) {
                            hydrateScripts(node);
                        }
                    });
                })
                .catch(function () {
                    target.remove();
                });
        }

        function loadVisibleSidebars() {
            document.querySelectorAll('[data-home-async="sidebar"]').forEach(loadSidebar);
        }

        loadVisibleSidebars();
        window.addEventListener('resize', loadVisibleSidebars, { passive: true });
    })();
</script>


