    <script>

        const form = document.querySelector("#formincluirevento");

        async function sendData() {
          // Associate the FormData object with the form element
          const formData = new FormData(form);

          try {
            const response = await fetch("/api/incluir_evento.cfm", {
              method: "POST",
              // Set the FormData instance as the request body
              body: formData,
            });
            const resposta = await response.json();
            const mensagemmodalincluirevento = document.getElementById('mensagemmodalincluirevento');
            const successTemplate = "Informação enviada com sucesso. Ticket aberto com o número {ticket}.";
            const closeLabel = "Fechar janela";
